const record = items[0]?.json || {};
if (!record || Object.keys(record).length === 0) {
  return [];
}
const rawCities = record.top_cities ?? record.major_cities ?? record.cities ?? [];
let cities = [];
if (Array.isArray(rawCities)) {
  cities = rawCities;
} else if (typeof rawCities === 'string' && rawCities.trim()) {
  try {
    const parsed = JSON.parse(rawCities);
    if (Array.isArray(parsed)) {
      cities = parsed;
    } else {
      cities = rawCities.split(/[,;
]/);
    }
  } catch (error) {
    cities = rawCities.split(/[,;
]/);
  }
} else if (rawCities && typeof rawCities === 'object') {
  cities = Object.values(rawCities);
}
cities = cities
  .filter(Boolean)
  .map((city) => city.toString().trim())
  .filter((city) => city.length > 0);
if (record.capital && !cities.includes(record.capital)) {
  cities.unshift(record.capital);
}
const topCities = Array.from(new Set(cities)).slice(0, 5);
if (topCities.length === 0 && record.capital) {
  topCities.push(record.capital);
}
const focusCities = topCities.length > 0 ? topCities.join(', ') : 'key urban centers';
const context = record.context || record.narrative_context || '';
const countryName = record.country_name || record.countryName || 'the country';
const countryCode = record.country_code || record.countryCode || record.iso2 || record.iso_2 || record.cca2 || '';
const language = record.primary_language || record.language || 'English';
const articlePrompt = [
  'You are an expert travel writer creating evergreen destination content for a live geography insights dashboard.',
  `Write a 300-word English article about ${countryName}.`,
  'Structure it with: an inviting introduction, geography & climate, economy & innovation, cultural highlights, and a practical travel tips conclusion.',
  `Reference these priority cities: ${focusCities}.`,
  context ? `Incorporate this strategic briefing: ${context}.` : '',
  'Keep the tone informative yet inspiring, avoid bullet lists, and stay between 290 and 310 words.'
].filter(Boolean).join(' ');
const imagePrompt = [
  `Generate five unique high-resolution square map illustrations for ${countryName}${countryCode ? ` (${countryCode})` : ''}.`,
  `Each map must spotlight ${focusCities} with clear city markers and accurate coastlines or borders.`,
  'Variation 1: Political-style map with regional boundaries and a highlighted capital.',
  'Variation 2: Topographic relief map emphasizing terrain, mountains, and waterways.',
  'Variation 3: Nighttime satellite-inspired map showing illuminated metropolitan areas.',
  'Variation 4: Minimalist contour map with pastel palette, rivers, and typography.',
  'Variation 5: Tourist infographic map showcasing landmarks and major transport corridors.',
  'Use English labels and keep compositions ready for a content dashboard.'
].join(' ');
return [
  {
    json: {
      queueId: record.id ?? null,
      countryCode,
      countryName,
      capital: record.capital || '',
      region: record.region || '',
      subregion: record.subregion || '',
      primaryLanguage: language,
      narrativeContext: context,
      topCities,
      focusCities,
      articlePrompt,
      imagePrompt
    }
  }
];

const source = items[0]?.json || {};
const mapData = Array.isArray(source.data) ? source.data : [];
const imageUrls = mapData
  .map((entry) => entry.url || (entry.b64_json ? `data:image/png;base64,${entry.b64_json}` : null))
  .filter(Boolean);
const article = source.articleText || (source.message && source.message.content) || '';
const wordCount = article
  .replace(/\s+/g, ' ')
  .trim()
  .split(' ')
  .filter(Boolean)
  .length;
const topCities = Array.isArray(source.topCities) ? source.topCities : [];
const sanitizeText = (value) => {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  return value.toString().replace(/'/g, "''");
};
const sanitizeJson = (value) => JSON.stringify(value ?? []).replace(/'/g, "''");
const toSqlText = (value) => {
  const sanitized = sanitizeText(value);
  return sanitized === null ? 'NULL' : "'" + sanitized + "'";
};
const toSqlJson = (value) => "'" + sanitizeJson(value) + "'::jsonb";
const narrative = source.narrativeContext || '';
const generatedAt = new Date().toISOString();
return [
  {
    json: {
      queueId: source.queueId ?? null,
      countryCode: (source.countryCode || '').toString(),
      countryName: source.countryName || '',
      capital: source.capital || '',
      region: source.region || '',
      subregion: source.subregion || '',
      primaryLanguage: source.primaryLanguage || 'English',
      narrativeContext: narrative,
      topCities,
      articleText: article,
      wordCount,
      imageUrls,
      articlePrompt: source.articlePrompt,
      imagePrompt: source.imagePrompt,
      generatedAt,
      sql: {
        countryCode: toSqlText(source.countryCode || ''),
        countryName: toSqlText(source.countryName || ''),
        capital: toSqlText(source.capital || ''),
        region: toSqlText(source.region || ''),
        subregion: toSqlText(source.subregion || ''),
        primaryLanguage: toSqlText(source.primaryLanguage || 'English'),
        narrativeContext: toSqlText(narrative),
        topCities: toSqlJson(topCities),
        articleText: toSqlText(article),
        imageUrls: toSqlJson(imageUrls),
        generatedAt: "'" + generatedAt + "'::timestamptz"
      }
    }
  }
];
